. ~/.lexsi_env; cd ~/work; . ~/envB/bin/activate
up() { python model_card.py "$1" "$2" "$3" "$4" $5 && hf upload "$2" "$1" . --repo-type model --commit-message "Upload checkpoint and card" --quiet && echo "UPLOADED $2"; }
up ckpt/M1_drift tyb343/rounded-off-tiny-aya-bank-sft "Tiny Aya Global fine-tuned as an English + Hindi bank support assistant (benign data only)." "SafeTune PlainSFTTrainer, LoRA r16 merged, lr 1e-4, 2 epochs, 2,985 Banking77 questions with Adaption answers (1,994 EN, 998 hi-IN), cleaned by CuratorKIT."
up ckpt/R_wise50 tyb343/rounded-off-tiny-aya-bank-sft-wiseft "The bank assistant after a WiSE-FT repair (halfway interpolation back to Tiny Aya Global)." "SafeTune WiseFTTrainer alpha 0.5 applied to rounded-off-tiny-aya-bank-sft."
up ckpt/CR_wise50 tyb343/rounded-off-tiny-aya-bank-contam10-wiseft "Repair of a bank assistant that was fine-tuned on data with 10% harmful rows (WiSE-FT, alpha 0.5)." "SafeTune PlainSFTTrainer on 2,985 bank chats + 332 BeaverTails unsafe rows (the unsafe model itself is not published), then SafeTune WiseFTTrainer alpha 0.5." --research-only
up ckpt/CR_resta25 tyb343/rounded-off-tiny-aya-bank-contam10-resta "Repair of the contaminated bank assistant with RESTA (safety vector = Tiny Aya Global - Tiny Aya Base, alpha 0.25, DARE p=0.3)." "SafeTune ReStaTrainer alpha 0.25 applied to the contaminated fine-tune." --research-only
